import{_ as o,o as e,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1977年 · 顺风之悟","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1977年.md","filePath":"05_quotes/by-year/1977年.md"}'),l={name:"05_quotes/by-year/1977年.md"};function r(q,t,s,c,p,b){return e(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1977年-·-顺风之悟" tabindex="-1">1977年 · 顺风之悟 <a class="header-anchor" href="#_1977年-·-顺风之悟" aria-label="Permalink to &quot;1977年 · 顺风之悟&quot;">​</a></h1><blockquote><p>&quot;待在顺风的行业里有多么重要。&quot;——巴菲特（47岁）</p></blockquote><p>本页收录1977年致股东信中的经典语录。伯克希尔的纺织业务持续亏损，保险却大放异彩——正是在这一年，巴菲特提炼出了他最重要的投资认知之一：顺风行业胜于逆风行业。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;大多数公司将&#39;创纪录&#39;收益定义为每股收益创出新高。由于企业每年通常都会增加股本，比如说，股本增长10%、每股收益增长5%的管理业绩，在我们看来并没有什么特别值得称道的。&quot;——巴菲特（47岁）</p></blockquote><blockquote><p>&quot;衡量管理经济表现更合适的指标是股本回报率，而非每股收益增长。&quot;</p></blockquote><blockquote><p>&quot;待在顺风而非逆风的行业里有多么重要。&quot;</p></blockquote><blockquote><p>&quot;保险行业高度放大了管理者个人对公司业绩的影响。我们非常幸运，能拥有这样一批管理者和我们一起。&quot;</p></blockquote><blockquote><p>&quot;我们大多数大仓位股票都会持有很多年，我们投资决策的记分牌是长期企业业绩，不是某一天的价格。就像收购整个公司时过度关注短期前景是愚蠢的，我们认为，购买一家公司的小部分股权时，被预期的近期盈利或近期盈利趋势迷惑同样不理性。&quot;</p></blockquote><blockquote><p>&quot;我们选择可交易股权的方法，和我们整体收购企业时评估business的方法几乎一模一样。我们希望这家business：(1)是我们能理解的；(2)拥有良好的长期前景；(3)由诚实能干的人运营；(4)价格非常有吸引力。&quot;</p></blockquote><blockquote><p>&quot;通常我们不会为了预期短期股价上涨而买入股票。事实上，如果它们的business表现持续让我们满意，我们甚至欢迎我们持有的股票市场价格下跌，这样我们就能以更好的价格买到更多好东西。&quot;</p></blockquote><blockquote><p>&quot;我们买控股business，还是买部分股权，根本没区别。我们就是买business长期前景好，价格合理，管理好，我们不交易。&quot;</p></blockquote><blockquote><p>&quot;直接从市场购买少数股权，有时能以远低于谈判收购整家公司所需的价格，获得杰出企业的部分权益。通过二级市场持股，可以间接获得企业收购无法直接得到的便宜货。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1977年是巴菲特掌管伯克希尔的第13个年头，账面价值年增长31.9%，远超道琼斯指数的-7.4%。伯克希尔已横跨纺织、保险、银行、出版等多个领域。保险业务由菲尔·利奇掌舵的国民赔偿公司领衔，实现了创纪录增长；纺织业务则持续低迷。本年最核心的认知升级：保险行业再优秀的管理者也只能带来有限回报，因为行业的本质就是&quot;顺风&quot;；而好行业中普通的管理者，也能获得不错的回报。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1977年/翻译.html">01_letters/1977年/翻译</a> · <a href="/01_letters/1977年/核心总结.html">01_letters/1977年/核心总结</a> · <a href="/01_letters/1977年/思维导图.html">01_letters/1977年/思维导图</a></p>',20)])])}const i=o(l,[["render",r]]);export{n as __pageData,i as default};
